+
+  /// Returns the held-back tail (a final line without its newline), minus
+  /// warning noise; call once when the stage ends.
+  List<int> flush() {
+    final rest = _carry;
+    _carry = '';
+    if (rest.isEmpty || isWasiPythonStderrNoise(rest)) return const <int>[];
+    return latin1.encode(rest);
+  }
+}
