+    test('byte-scan: no secret value reaches the rendered listing', () async {
+      env.registerSecretNames(['OTHER_KEY']);
+      await env.exec('env');
+      final merged = delegate.calls.single?.env ?? const {};
+      final listing = renderEnvListingWithSecretPresence(merged);
