    List<String> args,
    ShellExecOptions? options,
    String? inputSource,
  ) async {
    final parsed = parseCatArgs(args);
    if (parsed.error != null) return false;
    final files = [...parsed.files];
    if (files.isEmpty && inputSource != null) files.add(inputSource);
