        host: host,
        error: e,
        rid: rid,
        partialBytes: builder.length,
      );
      _logFailure(line);
      stderrLines.add(line);
    }
    if (quotaExceeded) {
      return _error(
        'curl: (63) response body exceeds the sandbox limit: received '
        '${builder.length} bytes, cap is $maxCurlResponseBytes\n',
        63,
      );
