+      });
+      expect(line, contains('FA_GITHUB_TOKEN: ABSENT'));
+      expect(line, contains('ANTHROPIC_API_KEY: ABSENT'));
+      expect(line, contains('PATH=/bin'));
+      expect(line.contains('$secretPresenceEnvVar='), isFalse);
+    });
+
