+  final bool number;
+
+  /// `-b` (overrides `-n` where both apply, like GNU cat).
+  final bool numberNonBlank;
+
+  /// Operand files in order; `-` means stdin.
+  final List<String> files;
+
+  /// GNU-shaped usage error, or null when the invocation is executable.
+  final String? error;
