+    late _CapturingEnv delegate;
+    late SecretsExecutionEnv env;
+
+    setUp(() {
+      delegate = _CapturingEnv();
+      env = SecretsExecutionEnv(delegate, {
+        'FA_GITHUB_TOKEN': 'ghp_supersecretvalue99',
+      });
+    });
