+    String command, {
+    ShellExecOptions? options,
+  }) async {
+    calls.add(options);
+    return const Ok(ShellExecResult(stdout: '', stderr: '', exitCode: 0));
+  }
+
+  @override
+  dynamic noSuchMethod(Invocation invocation) => super.noSuchMethod(invocation);
+}
