+      final merged = delegate.calls.single?.env ?? const {};
+      expect(merged['FA_GITHUB_TOKEN'], 'percall');
+      expect(merged[secretPresenceEnvVar], 'FA_GITHUB_TOKEN');
+    });
+  });
+}
