/// neither resolves — the caller falls through to a plain file read.
Future<ToolExecutionResult?> _readExtendedTarget(
  ExecutionEnv env,
  String rawPath,
  SplitReadPath split,
  SqliteEngine? sqlite,
  CancelToken? cancelToken,
