    if (cancelled) {
      return const Err(ExecutionError(ExecutionErrorCode.aborted, 'aborted'));
    }
    final exitCode = _parseExitCode(runError);
    if (exitCode != null) return Ok(exitCode);
    if (!hasOutput) {
