      result = await env.exec(
        command,
        options: ShellExecOptions(
          cwd: env.cwd,
          timeout: timeout,
          cancelToken: cancelToken,
          stdinData: stdinData,
        ),
      );
    } on TimeoutException {
      // An outer layer's future cap fired (transport hang); the exec
      // itself never answered.
      if (!canRetry) rethrow;
      notices.add(
        '[bash attempt $attempt/${bashToolMaxRetries + 1} hung — '
        'retrying]',
