    for (final arg in args) {
      final idx = arg.indexOf('=');
      if (idx > 0) {
        final name = arg.substring(0, idx);
        // Special parameters (`$?`) are shell-owned (issue #1335).
        if (!exportEnvVarName.hasMatch(name)) continue;
        _shellEnv[name] = arg.substring(idx + 1);
      } else {
