  final parsed = parseCurlArgs(args);
  if (parsed.url == null) {
    return _error('curl: no URL specified\n', 2);
  }

  Uri uri;
  try {
    uri = Uri.parse(parsed.url!);
  } on FormatException {
    return _error('curl: invalid URL\n', 3);
  }

  final (bodyBytes, bodyError) = await _curlBody(
    parsed.dataArgs,
    stdinBytes: stdinBytes,
  );
