Future<SandboxBuiltinResult> curl(
  List<String> args, {
  List<int>? stdinBytes,
  Duration? timeout,
}) async {
  final prelude = _curlPrelude(args);
  if (prelude != null) return prelude;
  final parsed = parseCurlArgs(args);
  if (parsed.url == null) {
    return _error('curl: no URL specified\n', 2);
  }

  Uri uri;
  try {
    uri = Uri.parse(parsed.url!);
  } on FormatException {
    return _error('curl: invalid URL\n', 3);
  }

  final (bodyBytes, bodyError) = await _curlBody(
    parsed.dataArgs,
    stdinBytes: stdinBytes,
  );
  if (bodyError != null) return _error(bodyError, 26);

{"path":"outputs/pr_review_comments/comment-bridge-host-ipv6.md","content":"💡 **SUGGESTION: `bridgeHostOfAuthority` mangles IPv6 literals**

`host.indexOf(':')` slices at the **first** colon, so an IPv6 authority is mis-rendered:

- `http://[::1]:8080/x` → host `[::1]` (brackets kept — never matches a `localhost`/`127.0.0.1` loopback check downstream),
- `[::1]:443` → the `:443` strip then cuts at index 0 → empty host.

Display-only today (failure lines), but it's cheap to be correct with the platform parser:

```dart
String bridgeHostOfAuthority(String authority) {
  final uri = Uri.parse(authority);
  return uri.host; // strips scheme, port, path, and IPv6 brackets
}
```

(Fall back to the current manual parse only if `Uri.parse` can throw on inputs this function receives.)
